const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function openSportsResort(host,{exit,notify,cameraFactory=o=>new SportsCamera(o)}={}){let disposed=false,serial=0,runtime=null,view=null,input=null,sound=null,music=null,camera=null,match=null,phase='hub',beforePause='aim',ids=[DB.active],controls=['camera','controller'],mode='quick',difficulty=2,quality='low',hand='right',aim=0,power=.65,curve=0,recorded=false,readyTracking=false,inferred=false,lastFrame=null,rollInputs=[],usedInputs=[],timer=0,raf=0,lastTime=0,acc=0,stroke=0,diagnostic=false,diagnosticPeople=1,pendingOutcome=null;const clean=[],q=s=>host.querySelector(s);let gate=createInstructionGate({game:'resort',onBack:hub,onReview(){pause('Review the rules.');return()=>{};}});
 function stopCamera(){camera?.stop();readyTracking=false;view?.setPose(null);if(q('#rsCameraState'))q('#rsCameraState').textContent='CAMERA OFF';if(q('#rsSkeleton')){const c=q('#rsSkeleton');c.getContext('2d').clearRect(0,0,c.width,c.height);}if(q('#rsCalProgress'))q('#rsCalProgress').value=0;}
 function cleanup(){serial++;clearTimeout(timer);cancelAnimationFrame(raf);stopCamera();camera?.dispose();camera=null;lastFrame=null;input?.dispose();input=null;view?.dispose();view=null;runtime?.dispose();runtime=null;sound?.dispose();sound=null;music?.dispose();music=null;for(const c of clean.splice(0))c();muteBackground(false);}
 const avatar=id=>player(id)?.sportsResort?.avatar||{shirt:'#72bfb5',hair:'waves',accessory:'none'};
 function hub(){cleanup();match=null;phase='hub';host.innerHTML=`<section class="resort rs-hub"><header><button id="rsExit" class="btn secondary">← ARCADE</button><span class="eyebrow">LITTLE BIG SPORTS RESORT · FIRST PLAYABLE CHECKPOINT</span></header><h1>A little motion.<br>A big day out.</h1><p>Original resort sports, local camera controls and friendly family play. Bowling is ready; the remaining sports will arrive in their own tested milestones.</p><div class="rs-sports">${Object.entries(SPORT_NAMES).map(([id,name])=>`<article>${sportArt(id)}<h2>${name}</h2><p>${id==='bowling'?'Ten frames · real ball/pin contacts · solo or two-player turns · webcam/controller/touch':'Planned · '+({tennis:'Milestone 3 · rallies, AI and tracked racket swings',boxing:'Milestone 4 · safe measured punches and guard',baseball:'Milestone 5 · batting and home-run challenges',golf:'Milestone 5 · club swings and multiple holes'})[id]}</p>${id==='bowling'?'<button id="rsBowling" class="btn primary">PLAY BOWLING</button>':'<span class="tag">NOT PLAYABLE YET</span>'}</article>`).join('')}</div><button id="rsDiagnostics" class="btn secondary">CAMERA & MOTION DIAGNOSTICS</button><p>Camera remains off until you acknowledge instructions and press Enable webcam. Processing stays on this device; no microphone, recording, uploads or facial identification.</p></section>`;q('#rsExit').onclick=exit;q('#rsBowling').onclick=setup;q('#rsDiagnostics').onclick=()=>gate.show({mode:'diagnostics',difficulty:'MOTION DIAGNOSTICS',players:[player().name]},()=>startDiagnostics());}
 function setup(){cleanup();match=null;phase='setup';host.innerHTML=`<section class="resort"><header><button id="rsHub" class="btn secondary">← SPORTS HUB</button><h1>Bowling at Bluewater Pier</h1></header><div class="rs-setup"><div>${sportArt('bowling')}<p>Keep a comfortable clear play area. Use short relaxed swings, with empty hands. No physical ball or sporting equipment is needed. Others stand aside during an alternating webcam turn.</p></div><div><label>Game<select id="rsMode"><option value="quick">Quick play · ten frames</option><option value="practice">Practice · unranked ten frames</option><option value="challenge">Challenge · reach the target score</option></select></label><label>Players<select id="rsPlayers"><option value="1">Solo · personal best</option><option value="2" ${DB.profiles.length<2?'disabled':''}>Two players · alternating frames</option></select></label><label>Partner<select id="rsPartner">${DB.profiles.filter(p=>p.id!==DB.active).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Player 1 control<select id="rsInput1">${options('camera')}</select></label><label>Player 2 control<select id="rsInput2">${options('controller')}</select></label><label>Challenge / aim assistance<select id="rsDifficulty">${['Easy · guided release','Normal','Hard','Very Hard','Expert · minimal assistance'].map((s,i)=>`<option value="${i+1}" ${difficulty===i+1?'selected':''}>${s}</option>`).join('')}</select></label><label>Graphics<select id="rsQuality"><option value="low">Low · prioritize camera responsiveness</option><option value="medium">Medium</option><option value="high">High</option></select></label><label>Bowling hand<select id="rsHand"><option value="right">Right</option><option value="left">Left</option></select></label></div></div><details><summary>Customize your active profile’s resort avatar</summary><div class="rs-custom"><label>Shirt<input id="rsShirt" type="color" value="${avatar(DB.active).shirt}"></label><label>Hair<select id="rsHair">${['waves','crop','tall'].map(s=>`<option ${avatar(DB.active).hair===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Accessory<select id="rsAccessory"><option value="none">None</option><option value="band" ${avatar(DB.active).accessory==='band'?'selected':''}>Headband</option></select></label></div></details><button id="rsStart" class="btn primary">LET’S BOWL</button><p>Ten-frame rules include strikes, spares and tenth-frame bonus balls. Controller: left stick aims; hold/release RT for power or A for a standard throw. Touch uses aim/power/spin and Roll. Keyboard arrows aim, hold/release Space throws. Motion and fallback records remain separate.</p><div class="rs-records"><h2>Personal records · Bowling</h2>${['camera','controller','touch'].map(source=>`<p>${source}: ${Math.max(0,...player().results.filter(r=>r.game==='resort'&&r.ruleset==='resort-bowling-v1'&&r.details?.inputSequence?.every(s=>s===source)).map(r=>r.score))}</p>`).join('')}</div></section>`;q('#rsHub').onclick=hub;q('#rsStart').onclick=()=>{mode=q('#rsMode').value;difficulty=+q('#rsDifficulty').value;quality=q('#rsQuality').value;hand=q('#rsHand').value;controls=[q('#rsInput1').value,q('#rsInput2').value];ids=[DB.active];if(q('#rsPlayers').value==='2'){const id=q('#rsPartner').value;if(!id||id===ids[0])return notify('Choose a different player.');ids.push(id);}player().sportsResort={avatar:{shirt:q('#rsShirt').value,hair:q('#rsHair').value,accessory:q('#rsAccessory').value}};save();gate.show({mode,modeLabel:'BOWLING · '+(ids.length===2?'ALTERNATING FRAMES':'SOLO'),difficulty:'LEVEL '+difficulty,players:ids.map(id=>player(id).name)},startMatch);};}
 const options=selected=>[['camera','Webcam motion'],['controller','Native controller'],['touch','Touch / mouse / keyboard']].map(([id,name])=>`<option value="${id}" ${selected===id?'selected':''}>${name}</option>`).join('');
 function cameraMarkup(){return `<aside class="rs-camera"><h2>Local motion view</h2><div class="rs-preview"><video id="rsVideo" muted playsinline></video><canvas id="rsSkeleton" aria-label="Measured shoulder, elbow, wrist and coarse hand landmarks"></canvas></div><strong id="rsCameraState" role="status">CAMERA OFF</strong><p id="rsTracking" role="status">Enable your camera when you are ready.</p><progress id="rsCalProgress" value="0" max="700" aria-label="Calibration hold"></progress><label>Camera<select id="rsCamera"><option value="">Default webcam</option></select></label><div class="rs-actions"><button id="rsEnable" class="btn primary">ENABLE WEBCAM</button><button id="rsCameraOff" class="btn secondary">CAMERA OFF</button><button id="rsRecalibrate" class="btn secondary">RECALIBRATE</button></div><div class="rs-actions"><label><input id="rsMirror" type="checkbox" checked>Mirror preview & aim</label><label>Preferred hand<select id="rsPreferred"><option value="right" ${hand==='right'?'selected':''}>Right</option><option value="left" ${hand==='left'?'selected':''}>Left</option></select></label><label>Sensitivity<input id="rsSensitivity" type="range" min=".7" max="1.4" step=".05" value="1"></label><label>Confidence<input id="rsConfidence" type="range" min=".45" max=".75" step=".05" value=".55"></label></div><output id="rsDiagnosticsStatus"></output><ol id="rsEvents" class="rs-events" aria-label="Recent measured gestures"></ol></aside>`;}
 async function startDiagnostics(){cleanup();diagnostic=true;phase='diagnostics';host.innerHTML=`<section class="resort"><header><button id="rsHub" class="btn secondary">← SPORTS HUB</button><h1>Motion diagnostics</h1></header><p>Stand centered, relax both arms, gently raise them and return to neutral. Measured events appear below; no sport is scored here. Pose tracks the body and coarse wrist/thumb/index/pinky hand points, not all finger joints. Monocular depth and throw strength are estimates, not physical measurements.</p><label>People in diagnostic view<select id="rsPeople"><option value="1">One person</option><option value="2">Two people · diagnostic separation only</option></select></label>${cameraMarkup()}</section>`;q('#rsHub').onclick=hub;wireCamera();q('#rsPeople').onchange=e=>{diagnosticPeople=+e.target.value;camera.players=diagnosticPeople;camera.calibrate();};}
 async function startMatch(){cleanup();diagnostic=false;const token=serial;phase='loading';match=new BowlingMatch({players:ids.length,mode,difficulty});recorded=false;pendingOutcome=null;usedInputs=[];rollInputs=[];aim=0;power=.65;curve=0;acc=0;host.innerHTML=`<section class="resort rs-game" data-native-gamepad="false"><header><button id="rsHub" class="btn secondary">← SPORTS HUB</button><h1>Bluewater Bowling</h1><button id="rsPause" class="btn secondary">PAUSE</button><button id="rsRestart" class="btn secondary">RESTART</button><button id="rsFull" class="btn secondary">FULLSCREEN</button></header><strong id="rsStatus" role="status">Loading the local 3D alley…</strong><div id="rsScorecard"></div><div class="rs-play-layout"><div><canvas id="rsCanvas" tabindex="0" aria-label="Three-dimensional bowling lane, ball and real physics pins"></canvas><div id="rsOverlay" class="rs-overlay"></div><div class="rs-aim-controls"><label>Aim · lane alignment<input id="rsAim" type="range" min="-1" max="1" step=".01" value="0"></label><label>Throw strength<input id="rsPower" type="range" min=".15" max="1" step=".01" value=".65"></label><label>Hook / spin<input id="rsCurve" type="range" min="-.6" max=".6" step=".05" value="0"></label><button id="rsRoll" class="btn primary">ROLL BALL · FALLBACK</button></div><div class="rs-actions"><button id="rsUseTouch" class="btn secondary">USE TOUCH / KEYBOARD</button><button id="rsUseController" class="btn secondary">USE CONTROLLER</button><button id="rsUseCamera" class="btn secondary">USE WEBCAM</button></div><output id="rsMetrics"></output><p>Webcam: first relax, then make a small backswing and forward release. Keep the preferred hand in view. The preview measures motion; aim assistance compensates for a single camera’s limitations. Empty hands and a clear play area only.</p></div>${cameraMarkup()}</div><div id="rsResult" hidden></div></section>`;q('#rsHub').onclick=hub;q('#rsPause').onclick=()=>phase==='paused'?resume():pause();q('#rsRestart').onclick=startMatch;q('#rsFull').onclick=()=>document.querySelector('#fullscreen')?.click();q('#rsAim').oninput=e=>aim=+e.target.value;q('#rsPower').oninput=e=>power=+e.target.value;q('#rsCurve').oninput=e=>curve=+e.target.value;q('#rsRoll').onclick=()=>{if(controls[match.active]!=='touch')return notify('Choose Use touch/keyboard first; camera throws never come from a button.');launch(power,'touch');};q('#rsUseTouch').onclick=()=>changeInput('touch');q('#rsUseController').onclick=()=>changeInput('controller');q('#rsUseCamera').onclick=()=>changeInput('camera');wireCamera();
 const hide=()=>{if(document.hidden){pause('Tab hidden. Camera is off; explicitly enable it again when ready.');stopCamera();}},blur=()=>pause('Focus changed. Resume when ready.');document.addEventListener('visibilitychange',hide);window.addEventListener('blur',blur);clean.push(()=>document.removeEventListener('visibilitychange',hide),()=>window.removeEventListener('blur',blur));
 try{const r=await create3DScene(q('#rsCanvas'),{quality,camera:{radius:20,alpha:Math.PI/2,beta:1.02,target:[0,.3,-1],minRadius:14,maxRadius:58},lighting:{ambient:.65,sun:1.05},onError:e=>{pause('Rendering stopped. Restart or return to the hub.');notify(e.message,'error');}});if(disposed||token!==serial){r.dispose();return;}runtime=r;r.engine.canvasTabIndex=0;view=createBowlingScene(r,{getSettings:()=>DB.settings});view.rack(match.standing,true);sound=createSynthAudio({contextFactory:audio,ownsContext:false,getSettings:()=>({muted:DB.settings.muted||document.hidden,volume:DB.settings.sound/100*.1})});sound.resume();muteBackground(true);input=bowlingInput({getState:()=>({active:phase==='aim',camera:controls[match.active]==='camera',controller:controls[match.active]==='controller',owner:match.active}),aim(delta){aim=Math.max(-1,Math.min(1,aim+delta));q('#rsAim').value=aim;},throwBall:launch,pause,help:()=>gate.review()});runtime.setUpdate(dt=>frame(dt));runtime.pause(true);if(phase==='paused'||document.hidden){phase='paused';overlay('Take a breath.','Resume intentionally to prepare this turn.');}else prepareTurn(true);scorecard();}catch(e){if(token!==serial||disposed)return;pause('The 3D alley could not start. Choose the hub or retry.');q('#rsStatus').textContent=e.message;notify(e.message,'error');}}
 function wireCamera(){camera=cameraFactory({onStatus(message){readyTracking=false;if(q('#rsCameraState'))q('#rsCameraState').textContent=q('#rsVideo')?.srcObject?.getVideoTracks().some(t=>t.readyState==='live')?'● CAMERA ACTIVE · LOCAL PROCESSING':'CAMERA OFF';if(q('#rsTracking'))q('#rsTracking').textContent=message;if(phase==='aim'&&controls[match?.active]==='camera')pause('Tracking stopped. Re-enable the camera or choose a fallback.');},onFrame(sample){lastFrame=sample;readyTracking=sample.ready&&!sample.slow&&sample.latency<250&&sample.ageMs<250;if(q('#rsTracking'))q('#rsTracking').textContent=sample.message;if(q('#rsCameraState'))q('#rsCameraState').textContent=camera.active?'● CAMERA ACTIVE · LOCAL PROCESSING':'CAMERA OFF';if(q('#rsCalProgress'))q('#rsCalProgress').value=sample.hold;if(q('#rsDiagnosticsStatus'))q('#rsDiagnosticsStatus').textContent=`${sample.backend} · ${sample.latency?.toFixed(0)||0} ms inference · ${sample.inferenceMedian?.toFixed(0)||0} ms median · ${sample.ageMs?.toFixed(0)||0} ms frame age · ${sample.trackingFps?sample.trackingFps.toFixed(1)+' measured fps':'warming up'} · ${sample.raw} person(s) · ${sample.phase} · coarse hand landmarks`;if(q('#rsEvents'))q('#rsEvents').innerHTML=camera.events.slice(-8).reverse().map(e=>`<li>P${e.owner+1} · ${esc(e.type)}${e.hand?' · '+esc(e.hand):''}${e.power?' · estimated strength '+Math.round(e.power*100)+'%':''}</li>`).join('');drawTracking(sample.bodies);if(phase==='aim'&&controls[match.active]==='camera'){if(!readyTracking){pause('Arms or tracking lost. Bring the current bowler back, then Resume.');return;}view?.setPose(sample.bodies[0]);for(const event of sample.events)if(event.type==='throw')launch(event.power,'camera',event.aim);}}});camera.hand=hand;camera.players=diagnostic?diagnosticPeople:1;q('#rsEnable').onclick=async()=>{const owner=camera,token=serial;q('#rsEnable').disabled=true;try{await owner.start(q('#rsVideo'),q('#rsCamera').value);if(disposed||token!==serial||camera!==owner||!owner.active)return;const devices=await owner.devices();if(disposed||token!==serial||camera!==owner||!q('#rsCamera'))return;const selected=q('#rsCamera').value;q('#rsCamera').innerHTML='<option value="">Default webcam</option>'+devices.filter(d=>d.kind==='videoinput').map((d,i)=>`<option value="${esc(d.deviceId)}">${esc(d.label||'Camera '+(i+1))}</option>`).join('');q('#rsCamera').value=selected;if(!diagnostic&&phase==='calibration')q('#rsStatus').textContent='Calibrate, then press READY TO BOWL.';}catch(e){owner.stop();if(token===serial&&q('#rsTracking'))q('#rsTracking').textContent=e.message+' Controller/touch remain available.';}finally{if(token===serial&&q('#rsEnable'))q('#rsEnable').disabled=false;}};q('#rsCameraOff').onclick=()=>{stopCamera();if(!diagnostic&&controls[match?.active]==='camera')pause('Camera off. Choose a fallback or enable it again.');};q('#rsRecalibrate').onclick=()=>{if(!diagnostic)pause('Recalibrate, then Resume.');camera.calibrate();readyTracking=false;};q('#rsCamera').onchange=()=>{stopCamera();if(!diagnostic&&controls[match?.active]==='camera')pause('Camera changed. Enable and recalibrate before resuming.');};for(const [id,key]of [['rsMirror','mirror'],['rsSensitivity','sensitivity'],['rsConfidence','confidence'],['rsPreferred','hand']])q('#'+id).onchange=e=>{if(key==='hand'){hand=e.target.value;view?.setHand(hand);}camera[key]=key==='mirror'?e.target.checked:key==='hand'?e.target.value:+e.target.value;if(key==='mirror')q('#rsVideo').style.transform=e.target.checked?'scaleX(-1)':'none';readyTracking=false;camera.calibrate();if(!diagnostic&&phase==='aim')pause('Tracking settings changed. Recalibrate before resuming.');};}
 function drawTracking(bodies=[]){const c=q('#rsSkeleton'),v=q('#rsVideo');if(!c||!v)return;c.width=v.videoWidth||640;c.height=v.videoHeight||360;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);for(const b of bodies){if(!b)continue;ctx.strokeStyle=b.owner?'#e8b68a':'#8fe1ce';ctx.lineWidth=3;for(const [a,z]of [[11,12],[11,13],[13,15],[12,14],[14,16],[11,23],[12,24],[23,24],[15,17],[15,19],[15,21],[16,18],[16,20],[16,22]]){const p=b.points[a],q=b.points[z];ctx.beginPath();ctx.moveTo(p.x*c.width,p.y*c.height);ctx.lineTo(q.x*c.width,q.y*c.height);ctx.stroke();}ctx.fillStyle=ctx.strokeStyle;ctx.font='20px sans-serif';ctx.fillText('P'+(b.owner+1),b.center.x*c.width,b.center.y*c.height-20);}}
 function overlay(title,text,button='READY TO BOWL'){q('#rsOverlay').innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><button id="rsReady" class="btn primary">${button}</button>`;q('#rsReady').onclick=()=>{if(phase==='paused')resume();else readyTurn();};}
 function prepareTurn(fresh,turnChanged=false){if(q('#rsPause'))q('#rsPause').textContent='PAUSE';view?.rack(match.standing,fresh);view?.setPose(null);view?.setAvatar(avatar(ids[match.active]));view?.setHand(hand);runtime?.pause(true);phase=controls[match.active]==='camera'?'calibration':'handoff';if(turnChanged){stopCamera();camera.calibrate();}const name=player(ids[match.active]).name;overlay(name+'’s turn.',controls[match.active]==='camera'?'Enable webcam, calibrate the current bowler with others outside view, then press Ready.':'Choose your aim and strength, then press Ready. Native controller uses the current player’s assigned pad.');q('#rsStatus').textContent=`${name} · frame ${match.players[match.active].frame+1} · ${controls[match.active].toUpperCase()} · ${mode==='practice'?'UNRANKED PRACTICE':mode==='challenge'?'TARGET '+(90+difficulty*15):'TEN-FRAME GAME'}`;syncControls();}
 function readyTurn(){if(match.done)return;if(controls[match.active]==='camera'&&(!camera.active||!readyTracking)){notify('Finish live calibration first, or explicitly choose touch/controller.');return;}phase='aim';q('#rsOverlay').replaceChildren();runtime?.pause(false);input?.reset();syncControls();}
 function changeInput(source){if(!match||match.done||(phase==='rolling'||phase==='paused'&&beforePause==='rolling'))return notify('Finish this ball before changing controls.');controls[match.active]=source;stopCamera();camera.calibrate();if(phase==='ball-result'||phase==='paused'&&beforePause==='ball-result')prepareTurn(pendingOutcome?.fresh,pendingOutcome?.turnChanged);else prepareTurn(false);}
 function syncControls(){const el=q('.rs-game');if(el)el.dataset.nativeGamepad=phase==='aim'&&controls[match.active]!=='camera'?'true':'false';if(q('#rsRoll'))q('#rsRoll').disabled=phase!=='aim'||controls[match.active]!=='touch';}
 function pause(message='Take a breather.'){if(!match||match.done||phase==='hub'||phase==='setup')return;if(phase!=='paused')beforePause=phase;phase='paused';camera?.gestures?.reset();runtime?.pause(true);sound?.pause(true);input?.reset();syncControls();if(q('#rsPause'))q('#rsPause').textContent='RESUME';if(q('#rsOverlay'))overlay('Game paused.',typeof message==='string'?message:'The ball, scoring and clock are paused.','RESUME');}
 function resume(){if(!match||match.done)return;if(controls[match.active]==='camera'&&beforePause==='aim'&&(!camera.active||!readyTracking)){notify('Restore/calibrate tracking or choose a fallback.');return;}camera?.gestures?.reset();phase=beforePause==='loading'?'handoff':beforePause;q('#rsPause').textContent='PAUSE';sound?.pause(false);input?.reset();if(phase==='aim'||phase==='rolling'){q('#rsOverlay').replaceChildren();runtime?.pause(false);}else if(phase==='ball-result'){showBallResult(pendingOutcome);}else prepareTurn(false);syncControls();}
 function launch(strength,source,estimateAim=0){if(phase!=='aim'||source!==controls[match.active]||!runtime||!view||!match.begin())return;const assisted=aim+(source==='camera'?estimateAim*(.35+difficulty*.12):0);view.launch({aim:Math.max(-1,Math.min(1,assisted)),power:strength,curve,hand});usedInputs.push(source);rollInputs.push({owner:match.active,source});phase='rolling';view.setPose(null);q('#rsStatus').textContent='Ball rolling · real local pin physics';sound?.play({frequency:145,duration:.25,type:'triangle'});syncControls();}
 function scorecard(){if(!q('#rsScorecard')||!match)return;q('#rsScorecard').innerHTML=`<div class="rs-score-scroll" tabindex="0" role="region" aria-label="Ten-frame bowling scorecards"><table><caption>Ten frames · strikes X · spares / · bonuses wait for later rolls</caption><thead><tr><th scope="col">Bowler</th>${Array.from({length:10},(_,i)=>`<th scope="col">${i+1}</th>`).join('')}<th scope="col">Total</th></tr></thead><tbody>${match.players.map((p,i)=>{const frames=bowlingFrames(p.rolls);return `<tr><th scope="row">${esc(player(ids[i]).name)}</th>${Array.from({length:10},(_,j)=>{const f=frames[j];return `<td>${f?f.rolls.map((v,k)=>v===10?'X':k>0&&f.rolls[k-1]!==10&&v+f.rolls[k-1]===10?'/':v===0?'–':v).join(' '):'·'}<small>${f?.total??''}</small></td>`;}).join('')}<td>${match.scores()[i]}</td></tr>`;}).join('')}</tbody></table></div>`;}
 function frame(dt){if(!match||disposed)return;input?.update(dt);if(phase==='aim'||phase==='rolling')match.update(dt);view?.update(phase==='paused'?0:dt);if(phase==='rolling'&&view.resolved()){const outcome=match.resolve(view.fallen());pendingOutcome=outcome;sound?.play({frequency:outcome.strike?880:outcome.spare?740:440,duration:.3,type:'triangle'});view.cheer();runtime.pause(true);scorecard();if(match.done){finish();return;}showBallResult(outcome);syncControls();}if(runtime&&q('#rsMetrics')){const s=runtime.stats();q('#rsMetrics').textContent=`${runtime.software?'Canvas compatibility':'WebGL'} 3D · ${s.fps} FPS · ${s.meshes} active meshes · ${s.bodies} physics bodies · ${s.p95Ms.toFixed(1)}ms p95`;}}
 function showBallResult(outcome){phase='ball-result';q('#rsStatus').textContent=outcome.strike?'STRIKE!':outcome.spare?'SPARE!':outcome.split?'Split · '+outcome.roll+' pins down':outcome.roll+' pin(s) down';q('#rsOverlay').innerHTML='<h2>'+esc(q('#rsStatus').textContent)+'</h2><p>Review your score, then continue. No new ball rolls until you choose it.</p><button id="rsNext" class="btn primary">CONTINUE</button>';q('#rsNext').onclick=()=>prepareTurn(outcome.fresh,outcome.turnChanged);}
 function finish(){if(recorded)return;recorded=true;phase='results';runtime?.pause(true);stopCamera();input?.reset();syncControls();const scores=match.scores(),winner=match.winner(),target=90+difficulty*15;try{if(mode!=='practice'){const entries=ids.map((id,i)=>({id,score:scores[i],hits:match.players[i].rolls.reduce((a,b)=>a+b,0),duration:match.clock,elapsed:match.clock,completed:true,soloWin:mode==='challenge'?scores[i]>=target:scores[i]>=80,details:{sport:'bowling',rolls:match.players[i].rolls,inputSequence:rollInputs.filter(r=>r.owner===i).map(r=>r.source),mode}}));commitRound(entries,{game:'resort',difficulty,mode:ids.length===2?'versus':'solo',ruleset:'resort-bowling-v1',levelId:'ten-frame',competition:ids.length===2?'versus':'solo',challengeKey:mode+'|'+[...new Set(usedInputs)].sort().join('+'),winnerId:ids.length===2?winner===null?null:ids[winner]:undefined});for(const id of ids)unlock(player(id),'resort-bowler');save();}}catch(e){notify('Could not save the match: '+e.message,'error');}const result=q('#rsResult');result.hidden=false;result.innerHTML=`<h2>${mode==='practice'?'Practice complete.':ids.length===2?winner===null?'A friendly tie!':esc(player(ids[winner]).name)+' wins!':mode==='challenge'?scores[0]>=target?'Challenge complete!':'Another round awaits.':'Ten frames, well played.'}</h2><p>${ids.map((id,i)=>esc(player(id).name)+': '+scores[i]).join(' · ')}. ${mode==='practice'?'No ranked record or arcade XP was awarded.':'Scores are saved with game mode, difficulty and actual input sources separated.'}</p><button id="rsAgain" class="btn primary">PLAY AGAIN</button><button id="rsResultsHub" class="btn secondary">SPORTS HUB</button>`;q('#rsOverlay').replaceChildren();q('#rsAgain').onclick=startMatch;q('#rsResultsHub').onclick=hub;result.scrollIntoView({block:'nearest'});}
 hub();return()=>{disposed=true;cleanup();gate.dispose();host.replaceChildren();};
}
